window.CODE = Object.assign(window.CODE || {}, {"ch21/cost_model.py":"\"\"\"Back-of-the-envelope maths for one agent versus several. No AI needed: just arithmetic.\n\nEvery model call re-sends its whole context (Chapter 2). So what matters is:\n  how many calls each design makes, and how big each call's context is.\n\nRun:  python cost_model.py\n\"\"\"\nfrom dataclasses import dataclass\n\nPRICE_IN, PRICE_OUT = 0.40, 1.60      # US$ per million tokens: illustrative small-model prices; use your model's\nSYSTEM, TOOL_SCHEMA, TURN_OUT = 400, 120, 150   # tokens: base system prompt, per tool schema, per model reply\nTOOL_RESULT = 250                               # tokens added to history by each tool result\n\n\n@dataclass\nclass Design:\n    name: str\n    calls: list[tuple[int, int]]      # one (number_of_tools_visible, steps_already_in_history) per model call\n    parallel_groups: int              # how many sequential \"waves\" of calls (for latency)\n\n    def tokens(self) -> tuple[int, int]:\n        tin = sum(SYSTEM + n_tools * TOOL_SCHEMA + steps * (TURN_OUT + TOOL_RESULT) for n_tools, steps in self.calls)\n        return tin, len(self.calls) * TURN_OUT\n\n    def cost(self) -> float:\n        tin, tout = self.tokens()\n        return (tin * PRICE_IN + tout * PRICE_OUT) / 1_000_000\n\n\n# A task that needs 4 tool steps: check insurance, check schedule, check location, request booking.\nsingle = Design(\"One agent, 16 tools\", [(16, s) for s in range(5)], parallel_groups=5)\n# Supervisor decides one hand-off at a time (sees each result), each specialist makes 2 calls.\nsupervisor = Design(\"Supervisor, one specialist at a time\",\n                    [(4, k) for k in range(5)] + [(4, 0), (4, 1)] * 4, parallel_groups=13)\n# Supervisor plans once, all 4 specialists run at the same time, supervisor writes the answer.\nparallel = Design(\"Supervisor plans, specialists in parallel\",\n                  [(4, 0)] + [(4, 0), (4, 1)] * 4 + [(4, 4)], parallel_groups=4)\n\nif __name__ == \"__main__\":\n    print(f\"{'design':<44}{'calls':>6}{'tokens in':>11}{'cost (US$)':>12}{'waits':>7}\")\n    for d in (single, supervisor, parallel):\n        tin, _ = d.tokens()\n        print(f\"{d.name:<44}{len(d.calls):>6}{tin:>11,}{d.cost():>12.5f}{d.parallel_groups:>7}\")\n\n    largest = max(SYSTEM + 16 * TOOL_SCHEMA + 4 * (TURN_OUT + TOOL_RESULT), 0)\n    print(f\"\\nLargest single prompt, one agent: {largest:,} tokens with 16 tool schemas to choose from\")\n    print(f\"Largest single prompt, specialist: {SYSTEM + 4 * TOOL_SCHEMA + 1 * (TURN_OUT + TOOL_RESULT):,} tokens with 4 tools\")\n    print(f\"\\nAt 10,000 conversations a day: one agent ${single.cost() * 10_000:,.2f}, \"\n          f\"supervisor ${supervisor.cost() * 10_000:,.2f}\")\n","ch21/failure_guards.py":"\"\"\"Guards every multi-agent system needs, in plain Python. Chapters 23 and 27 reuse this idea.\n\n1. A shared budget across ALL agents (one runaway specialist cannot spend everything)\n2. A hand-off depth limit (A -> B -> C -> ... must end)\n3. Ping-pong detection (A -> B -> A -> B is a loop, not progress)\n\nRun:  python failure_guards.py\n\"\"\"\nfrom dataclasses import dataclass, field\n\n\nclass StopRun(Exception):\n    \"\"\"Raised when a guard stops the run. Catch it, log it, and hand over to a person.\"\"\"\n\n\n@dataclass\nclass RunGuard:\n    max_model_calls: int = 20\n    max_depth: int = 4\n    calls: dict = field(default_factory=dict)       # agent name -> model calls used\n    path: list = field(default_factory=list)        # hand-off path so far\n\n    def model_call(self, agent: str) -> None:\n        self.calls[agent] = self.calls.get(agent, 0) + 1\n        if sum(self.calls.values()) > self.max_model_calls:\n            raise StopRun(f\"budget: {sum(self.calls.values())} model calls; most by {max(self.calls, key=self.calls.get)}\")\n\n    def hand_off(self, to_agent: str) -> None:\n        self.path.append(to_agent)\n        if len(self.path) > self.max_depth:\n            raise StopRun(f\"depth: {' -> '.join(self.path)}\")\n        if len(self.path) >= 4 and self.path[-4:-2] == self.path[-2:]:\n            raise StopRun(f\"ping-pong: {' -> '.join(self.path[-4:])}\")\n\n\nif __name__ == \"__main__\":\n    for name, steps in {\n        \"normal\":    [(\"supervisor\", \"scheduling\"), (\"scheduling\", None), (\"scheduling\", None), (\"supervisor\", None)],\n        \"ping-pong\": [(\"supervisor\", \"billing\"), (\"billing\", \"insurance\"), (\"insurance\", \"billing\"), (\"billing\", \"insurance\")],\n        \"runaway\":   [(\"supervisor\", \"reports\")] + [(\"reports\", None)] * 25,\n    }.items():\n        guard = RunGuard(max_depth=6)\n        try:\n            for agent, handoff in steps:\n                guard.model_call(agent)\n                if handoff:\n                    guard.hand_off(handoff)\n            print(f\"{name:<10} finished: calls={guard.calls} path={guard.path}\")\n        except StopRun as stop:\n            print(f\"{name:<10} STOPPED  {stop}\")\n","ch21/tool_overload.py":"\"\"\"How big does one agent get when it does everything? Count the tools and their schema size.\n\nA real hospital helpdesk grows fast: schedules, bookings, billing, insurance, reports, directions...\nEvery tool's schema is sent with EVERY model call, and more choices means more wrong choices.\n\nRun:  python tool_overload.py\n\"\"\"\nimport json\n\nTEAMS = {\n    \"scheduling\": [\"get_doctor_schedule\", \"find_next_free_slot\", \"request_appointment\", \"cancel_appointment\"],\n    \"billing\":    [\"get_bill\", \"explain_charge\", \"create_refund_request\", \"get_payment_link\"],\n    \"insurance\":  [\"check_scheme_eligibility\", \"get_preauth_status\", \"list_covered_procedures\", \"start_preauth\"],\n    \"reports\":    [\"get_report_status\", \"send_report_link\", \"get_discharge_summary\", \"request_report_correction\"],\n}\nWRITE_TOOLS = {\"request_appointment\", \"cancel_appointment\", \"create_refund_request\", \"start_preauth\",\n               \"send_report_link\", \"request_report_correction\"}\n\n\ndef schema(name: str) -> dict:\n    \"\"\"A typical tool schema: name, a two-sentence description, three arguments.\"\"\"\n    return {\"type\": \"function\", \"function\": {\n        \"name\": name,\n        \"description\": f\"{name.replace('_', ' ').capitalize()} for a City Clinic patient. \"\n                       \"Use only when the patient has asked for this and given the required details.\",\n        \"parameters\": {\"type\": \"object\", \"required\": [\"patient_id\"], \"properties\": {\n            \"patient_id\": {\"type\": \"string\", \"description\": \"The patient's UHID, e.g. UHID-1001\"},\n            \"reference\": {\"type\": \"string\", \"description\": \"Bill, report, booking or claim number if known\"},\n            \"notes\": {\"type\": \"string\", \"description\": \"Anything else the patient said that is relevant\"}}}}}\n\n\ndef tokens(obj) -> int:\n    return len(json.dumps(obj)) // 4          # rough rule from Chapter 2: about 4 characters per token\n\n\nif __name__ == \"__main__\":\n    all_tools = [schema(t) for tools in TEAMS.values() for t in tools]\n    print(f\"One agent: {len(all_tools)} tools, ~{tokens(all_tools):,} tokens of schemas in every call, \"\n          f\"{len(WRITE_TOOLS)} of them can change records\")\n    for team, tools in TEAMS.items():\n        writes = [t for t in tools if t in WRITE_TOOLS]\n        print(f\"  {team:<11} specialist: {len(tools)} tools, ~{tokens([schema(t) for t in tools]):,} tokens, \"\n              f\"writes: {writes or 'none'}\")\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
